import math
import itertools

count = int(input())
for i in range(count):
    n = int(input())
    k = int(input())
    low = int(input())
    if n == 1:
        print(f"x_1 = {k}, each at least {low}")
    else:
        print(f"x_1 + ... + x_{n} = {k}, each at least {low}")
    left = k - n * low
    if left < 0:
        print(f"  {n} unknowns need at least {n * low}, more than {k}, so 0")
    else:
        print(f"  give each {low} first, leaving {left} to share")
        print(f"  stars and bars: C({n} + {left} - 1, {n} - 1) = {math.comb(n + left - 1, n - 1)}")
    listed = 0
    for xs in itertools.product(range(k + 1), repeat=n):
        if sum(xs) == k and all(x >= low for x in xs):
            listed = listed + 1
    print(f"  listed: {listed}")
